def mul(a, b):
    return (a * b) % mod

def pow(p, k):
    ret = 1
    b = p
    while k > 0:
        if k % 2 == 1:
            ret = mul(ret, b)
        b = mul(b, b)
        k //= 2
    return ret

def inv(p, k):
    return pow(p, mod - k - 1)

